def at(x,y,w,h,body,cls='',extra=''):return f'<div class="{cls}" style="position:absolute;left:{x}px;top:{y}px;width:{w}px;'+(f'height:{h}px;' if h else '')+extra+'">'+body+'</div>'
def icon(kind='check'):
 paths={'check':'<circle cx="12" cy="12" r="8" opacity=".4"/><path d="m9 11 3 3 8-8"/>','flag':'<path d="M5 21V3l14 5-14 5"/>','monitor':'<path d="M3 4h18v13H3zM8 21h8M12 17v4"/>','chart':'<path d="M4 20V9h4v11M10 20V3h4v17M16 20V7h4v13"/>','puzzle':'<path d="M4 4h6c-3 6 5 6 3 0h7v6c6-2 6 6 0 4v6h-6c2-6-6-6-4 0H4z"/>','briefcase':'<path d="M4 7h16v14H4zM8 7V3h8v4M9 11h6"/>','bulb':'<path d="M8 15a7 7 0 1 1 8 0v5H8zM9 23h6"/>','headphones':'<path d="M4 16v-4a8 8 0 0 1 16 0v4M4 13H1v7h4M20 13h3v7h-4"/>','user':'<circle cx="12" cy="6" r="4"/><path d="M4 23v-6a8 8 0 0 1 16 0v6z"/>','search':'<circle cx="10" cy="10" r="7"/><path d="m15 15 7 7"/>','arrow-up-right':'<path d="M2 22 22 2M7 2h15v15"/>','pie':'<path d="M21 12a9 9 0 1 1-9-9v9zM15 3v6h6a9 9 0 0 0-6-6z"/>','building':'<path d="M2 22V4h12v18M14 10h8v12M6 8h4M6 12h4M6 16h4"/>','edit':'<path d="M15 4H4v16h16v-8M10 15l12-12"/>'}
 return '<span class="icon"><svg viewBox="0 0 24 24">'+paths.get(kind,paths['check'])+'</svg></span>'
def arrow():return '<svg class="arrow" viewBox="0 0 40 40"><path d="M4 36 36 4M13 4h23v23" fill="none" stroke="#363636" stroke-width="5"/></svg>'
from waves import wave_svg
def wave(x=0,y=350,w=1280,h=370,flip=False):
 kind=1
 if x==-240:kind=2;x=0;y=0;w=520;h=440
 elif x==250:kind=3;x=0;y=0;w=1280;h=340
 elif x==-70:kind=4;x=0;y=500;w=212;h=220
 z=wave_svg(kind).replace('var(--a2-4-soft)','#42bdec').replace('var(--a1-4-soft)','#c287ee')
 return '<div class="wave" style="left:'+str(x)+'px;top:'+str(y)+'px;width:'+str(w)+'px;height:'+str(h)+'px;'+('transform:scaleX(-1);' if flip else '')+'">'+z+'</div>'
def base(n,title,desc='',active=0):
 sec=1 if n<=8 else 2 if n<=12 else 3 if n<=16 else 4
 names=['ABOUT<br>US','OUR<br>BUSINESS','OUR<br>VALUE','OUR<br>FUTURE']; menus=[['CEO MESSAGE','COMPANY OVERVIEW','MISSION & VISION','OUR HISTORY','ORGANIZATION'],['BUSINESS OVERVIEW','CORE BUSINESS 01','CORE BUSINESS 02','PRODUCTS & SERVICES'],['KEY STRENGTHS','PERFORMANCE','CERTIFICATIONS','PARTNERSHIP'],['GROWTH STRATEGY']]
 m='<br>'.join(('▸ ' if i==active else '')+v for i,v in enumerate(menus[sec-1]))
 return '<div class="rail"><div class="idx">0'+str(sec)+'</div><h2>'+names[sec-1]+'</h2><p>'+m+'</p><div class="logo"><i></i></div>'+wave(-70,525,350,200)+'</div><div class="dots" style="left:265px;top:1px;height:62px"></div><div class="dots" style="right:73px;bottom:1px;height:60px"></div>'+at(292,88,530,None,'<h1>'+title+'</h1>')+(at(755,105,410,None,desc,'intro2')+arrow() if desc else '')
def ph(x,y,w,h,num):return at(x,y,w,h,f'<span style="color:#aaa;font-size:17px">{num}</span>','panel','background:#e7e7e7;display:grid;place-items:center;border-radius:0;')
def chart(x,y,w,h,vals,line=None,title=''):
 maxi=100 if '컨설팅' in title else 200;unit='건' if maxi==100 else '명';ticks=5 if maxi==100 else 4;b='';pts=[];plotx=82;ploty=105;plotw=315;ploth=192;base=ploty+ploth
 grid=''.join(f'<path d="M{plotx} {ploty+j*ploth/ticks}H{plotx+plotw}" stroke="#ddd"/><text x="{plotx-6}" y="{ploty+j*ploth/ticks+4}" text-anchor="end" fill="#333" font-size="12">{round(maxi*(1-j/ticks))}{unit}</text>' for j in range(ticks+1))
 if line:
  pts=[(plotx+(i+.5)*plotw/len(vals),base-v/maxi*ploth) for i,v in enumerate(line)]
  b+='<polygon points="'+str(pts[0][0])+','+str(base)+' '+' '.join(f'{a},{z}' for a,z in pts)+' '+str(pts[-1][0])+','+str(base)+'" fill="#099ef3" opacity=".28"/>'
 for i,v in enumerate(vals):
  bx=plotx+(i+.17)*plotw/len(vals);bw=plotw/len(vals)*.66;by=base-v/maxi*ploth
  b+=f'<rect x="{bx}" y="{by}" width="{bw}" height="{base-by}" rx="11" fill="#a13cff"/><text x="{bx+bw/2}" y="{by+19}" text-anchor="middle" fill="white" font-size="14">{v}{unit}</text><text x="{bx+bw/2}" y="{base+19}" text-anchor="middle" fill="#333" font-size="12">{2080+i}</text>'
 if line:
  b+='<polyline points="'+' '.join(f'{a},{z}' for a,z in pts)+'" fill="none" stroke="#099ef3" stroke-width="2"/>'
  b+=''.join(f'<circle cx="{a}" cy="{z}" r="3" fill="#099ef3"/><text x="{a}" y="{z-12}" text-anchor="middle" fill="#099ef3" font-size="14">{v}{unit}</text>' for (a,z),v in zip(pts,line))
 labels=['프로젝트 수','재계약률'] if maxi==100 else ['임직원 수','고객사 수']
 b+=f'<rect x="159" y="340" width="11" height="11" rx="2" fill="#a13cff"/><text x="173" y="350" fill="#333" font-size="11">{labels[0]}</text><circle cx="237" cy="345" r="5" fill="#099ef3"/><text x="245" y="350" fill="#333" font-size="11">{labels[1]}</text>'
 return at(x,y,w,h,'<h2 style="margin:0 0 14px">'+title+'</h2><svg width="100%" height="100%" viewBox="0 0 '+str(w)+' '+str(h)+'" style="position:absolute;inset:0;font:15px Pretendard Variable">'+grid+b+'</svg>','panel')
